BEGIN;

-- STEP 1: products

-- STEP 2 & 3: deliveries + batches
SELECT setval('deliveries_delivery_id_seq', (SELECT MAX(delivery_id) FROM deliveries));

SELECT setval('batches_batch_id_seq', (SELECT MAX(batch_id) FROM batches));

-- STEP 4, 5 & 6: sales, waste, daily_stock_snapshot (simulated per product, day by day)
SELECT setval('sales_sale_id_seq', (SELECT MAX(sale_id) FROM sales));

SELECT setval('waste_waste_id_seq', (SELECT MAX(waste_id) FROM waste));

SELECT setval('daily_stock_snapshot_snapshot_id_seq', (SELECT MAX(snapshot_id) FROM daily_stock_snapshot));

COMMIT;

